/** Get all images for a product slug */
export function getProductImages(slug) {
  if (!slug) return ['/images/placeholder-pot.jpg'];
  const clean = String(slug).toLowerCase().trim();
  if (productImageMap[clean] && productImageMap[clean].length > 0) return productImageMap[clean];
  const key = Object.keys(productImageMap).find(k => clean.includes(k) || k.includes(clean));
  if (key && productImageMap[key].length > 0) return productImageMap[key];
  return ['/images/placeholder-pot.jpg'];
}

/** Get primary (first/main suitable) image */
export function getProductImage(slug) {
  return getProductImages(slug)[0];
}

/** Get image matching a specific color for a product */
export function getProductImageForColor(slug, color) {
  if (!slug) return '/images/placeholder-pot.jpg';
  const allImages = getProductImages(slug);
  if (!color || allImages.length === 0) return allImages[0] || '/images/placeholder-pot.jpg';

  const cClean = String(color).toLowerCase().trim();
  // Strip non-alphanumeric except spaces and slash
  const words = cClean.split(/[\s\/\-_]+/).filter(w => w && w !== 'transparent');
  const targetWords = words.length > 0 ? words : [cClean];

  // 1. Try finding image where filename includes ALL target words
  const fullMatch = allImages.find(img => {
    const fLower = img.toLowerCase();
    return targetWords.every(w => fLower.includes(w));
  });
  if (fullMatch) return fullMatch;

  // 2. Try matching the first significant color word (e.g. "pistachio", "lilac", "gold", "white")
  const primaryWord = targetWords[0];
  if (primaryWord) {
    const partialMatch = allImages.find(img => img.toLowerCase().includes(primaryWord));
    if (partialMatch) return partialMatch;
  }

  // 3. Fallback to main product image
  return allImages[0];
}